export const COMPANIES = [
 {symbol:'HBR',name:'Harbor Pantry',description:'Everyday groceries and household staples. Steady demand cushions economic shocks.',initial:48,volatility:.0007,sensitivity:.25,history:[46.8,47.1,46.9,47.5,47.8,48]},
 {symbol:'FRG',name:'Forge Works',description:'Industrial pumps and factory equipment. Orders depend on investment and the economy.',initial:82,volatility:.0013,sensitivity:1.5,history:[79,81,80,83,81.5,82]},
 {symbol:'LUM',name:'Lumen Cloud',description:'Fast-growing business software. Earnings surprises can sharply change growth expectations.',initial:125,volatility:.0022,sensitivity:.8,history:[112,120,116,123,119,125]}
];
const copy=x=>structuredClone(x);
export class Market {
 constructor(seed=42){this.restart(seed);}
 restart(seed=this.seed){if(!Number.isSafeInteger(seed)||seed<0||seed>4294967295)throw Error('Seed must be a whole number from 0 to 4294967295.');this.seed=seed;this.cash=10000;this.positions=COMPANIES.map(()=>({quantity:0,basis:0,realized:0}));this.prices=COMPANIES.map(c=>c.initial);this.day=0;this.closes=COMPANIES.map(c=>[...c.history]);this.nextDay();}
 nextDay(){if(this.day&&this.phase!=='review')throw Error('Finish this day first.');if(this.day)this.prices.forEach((p,i)=>{this.closes[i].push(p);this.closes[i]=this.closes[i].slice(-6);});this.day++;this.second=0;this.phase='preparation';this.randomState=(this.seed^Math.imul(this.day,0x9e3779b9))>>>0;this.timeline=[];this.histories=this.prices.map(p=>[p]);this.openPrices=[...this.prices];this.openEquity=this.equity;this.openUnrealized=this.positions.map((p,i)=>this.unrealized(i));this.openRealized=this.positions.map(p=>p.realized);this.largest={value:0,symbol:'None',second:0,quantity:0};this.trackLargest();this.target=(this.day-1)%3;this.expected=[.8,1.2,.6][this.target];this.reported=+(this.expected+(this.random()-.5)*.6).toFixed(2);this.macro=(this.random()-.5)*.035;}
 random(){this.randomState=(this.randomState+0x6D2B79F5)>>>0;let t=this.randomState;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;}
 get equity(){return this.cash+this.positions.reduce((s,p,i)=>s+p.quantity*this.prices[i],0);}
 quote(i){const mid=this.prices[i],spread=mid*.002;return {mid,bid:mid-spread/2,ask:mid+spread/2};}
 unrealized(i){const p=this.positions[i];return p.quantity*this.prices[i]-p.basis;}
 open(){if(this.phase!=='preparation')throw Error('Market is already open or closed.');this.phase='trading';}
 preview(i,side,input){if(!Number.isInteger(i)||i<0||i>=3)return {error:'Choose a listed company.'};if(!['buy','sell'].includes(side))return {error:'Choose buy or sell.'};const quantity=Number(input);if(String(input).trim()===''||!Number.isSafeInteger(quantity)||quantity<=0)return {error:'Enter a positive whole-share quantity.'};const p=this.positions[i],price=this.quote(i)[side==='buy'?'ask':'bid'],total=price*quantity,cash=this.cash+(side==='buy'?-total:total);if(side==='buy'&&total>this.cash)return {error:'Not enough cash for this purchase.'};if(side==='sell'&&quantity>p.quantity)return {error:'Cannot sell more shares than you own.'};const shares=p.quantity+(side==='buy'?quantity:-quantity),equity=this.equity-quantity*Math.abs(price-this.prices[i]);return {quantity,price,total,cash,exposure:shares*this.prices[i]/equity*100};}
 order(i,side,input){if(this.phase!=='trading')return {error:'Orders are accepted only while the market is open.'};const fill=this.preview(i,side,input);if(fill.error)return fill;const p=this.positions[i];if(side==='buy'){p.basis+=fill.total;p.quantity+=fill.quantity;}else{const cost=p.basis/p.quantity*fill.quantity;p.basis-=cost;p.quantity-=fill.quantity;p.realized+=fill.total-cost;if(!p.quantity)p.basis=0;}this.cash=fill.cash;this.timeline.push({type:'execution',second:this.second,symbol:COMPANIES[i].symbol,side,...fill});this.trackLargest();return fill;}
 trackLargest(){this.positions.forEach((p,i)=>{const value=p.quantity*this.prices[i];if(value>this.largest.value)this.largest={value,symbol:COMPANIES[i].symbol,second:this.second,quantity:p.quantity};});}
 tick(){if(this.phase!=='trading')return;this.second++;for(let i=0;i<3;i++)this.prices[i]=Math.max(.01,this.prices[i]*(1+(this.random()-.5)*2*COMPANIES[i].volatility));if(this.second===60){const effect=(this.reported-this.expected)/this.expected*[.04,.08,.18][this.target]+(this.random()-.5)*.012;this.event('earnings',this.prices.map((_,i)=>i===this.target?effect:0),`${COMPANIES[this.target].name} earnings: expected $${this.expected.toFixed(2)}, reported $${this.reported.toFixed(2)} per share.`);}if(this.second===120)this.event('economy',COMPANIES.map(c=>this.macro*c.sensitivity),`Capital spending survey ${this.macro>=0?'strengthened':'weakened'}. Forge is most sensitive; Harbor is least sensitive.`);this.prices.forEach((p,i)=>this.histories[i].push(p));this.trackLargest();if(this.second===180)this.phase='review';}
 event(type,effects,text){const before=[...this.prices];this.prices=this.prices.map((p,i)=>Math.max(.01,p*(1+effects[i])));this.timeline.push({type,second:this.second,text,effects:effects.map((fraction,i)=>({symbol:COMPANIES[i].symbol,fraction,before:before[i],after:this.prices[i]}))});}
 get review(){const companies=COMPANIES.map((c,i)=>({...c,realized:this.positions[i].realized-this.openRealized[i],unrealized:this.unrealized(i),changeInUnrealized:this.unrealized(i)-this.openUnrealized[i],daily:this.positions[i].realized-this.openRealized[i]+this.unrealized(i)-this.openUnrealized[i]}));return {opening:this.openEquity,closing:this.equity,daily:this.equity-this.openEquity,percent:(this.equity/this.openEquity-1)*100,companies,timeline:copy(this.timeline),largest:copy(this.largest)};}
}
